78	/**
79	 * Core implementation of Aliyun OSS Filesystem for Hadoop.
80	 * Provides the bridging logic between Hadoop's abstract filesystem and
81	 * Aliyun OSS.
82	 */
83	public class AliyunOSSFileSystemStore {
84	  public static final Logger LOG =
85	      LoggerFactory.getLogger(AliyunOSSFileSystemStore.class);
86	  private String username;
87	  private FileSystem.Statistics statistics;
88	  private OSSClient ossClient;
89	  private String bucketName;
90	  private long uploadPartSize;
91	  private int maxKeys;
92	  private String serverSideEncryptionAlgorithm;
