94	  public void initialize(URI uri, Configuration conf, String user,
95	                         FileSystem.Statistics stat) throws IOException {
96	    this.username = user;
97	    statistics = stat;
98	    ClientConfiguration clientConf = new ClientConfiguration();
99	    clientConf.setMaxConnections(conf.getInt(MAXIMUM_CONNECTIONS_KEY,
100	        MAXIMUM_CONNECTIONS_DEFAULT));
101	    boolean secureConnections = conf.getBoolean(SECURE_CONNECTIONS_KEY,
102	        SECURE_CONNECTIONS_DEFAULT);
103	    clientConf.setProtocol(secureConnections ? Protocol.HTTPS : Protocol.HTTP);
104	    clientConf.setMaxErrorRetry(conf.getInt(MAX_ERROR_RETRIES_KEY,
105	        MAX_ERROR_RETRIES_DEFAULT));
106	    clientConf.setConnectionTimeout(conf.getInt(ESTABLISH_TIMEOUT_KEY,
107	        ESTABLISH_TIMEOUT_DEFAULT));
108	    clientConf.setSocketTimeout(conf.getInt(SOCKET_TIMEOUT_KEY,
109	        SOCKET_TIMEOUT_DEFAULT));
110	    clientConf.setUserAgent(
111	        conf.get(USER_AGENT_PREFIX, USER_AGENT_PREFIX_DEFAULT) + ", Hadoop/"
112	            + VersionInfo.getVersion());
113	
114	    String proxyHost = conf.getTrimmed(PROXY_HOST_KEY, "");
115	    int proxyPort = conf.getInt(PROXY_PORT_KEY, -1);
116	    if (StringUtils.isNotEmpty(proxyHost)) {
117	      clientConf.setProxyHost(proxyHost);
118	      if (proxyPort >= 0) {
119	        clientConf.setProxyPort(proxyPort);
120	      } else {
121	        if (secureConnections) {
122	          LOG.warn("Proxy host set without port. Using HTTPS default 443");
123	          clientConf.setProxyPort(443);
124	        } else {
125	          LOG.warn("Proxy host set without port. Using HTTP default 80");
126	          clientConf.setProxyPort(80);
127	        }
128	      }
129	      String proxyUsername = conf.getTrimmed(PROXY_USERNAME_KEY);
130	      String proxyPassword = conf.getTrimmed(PROXY_PASSWORD_KEY);
131	      if ((proxyUsername == null) != (proxyPassword == null)) {
132	        String msg = "Proxy error: " + PROXY_USERNAME_KEY + " or " +
133	            PROXY_PASSWORD_KEY + " set without the other.";
134	        LOG.error(msg);
135	        throw new IllegalArgumentException(msg);
136	      }
137	      clientConf.setProxyUsername(proxyUsername);
138	      clientConf.setProxyPassword(proxyPassword);
139	      clientConf.setProxyDomain(conf.getTrimmed(PROXY_DOMAIN_KEY));
140	      clientConf.setProxyWorkstation(conf.getTrimmed(PROXY_WORKSTATION_KEY));
141	    } else if (proxyPort >= 0) {
142	      String msg = "Proxy error: " + PROXY_PORT_KEY + " set without " +
143	          PROXY_HOST_KEY;
144	      LOG.error(msg);
145	      throw new IllegalArgumentException(msg);
146	    }
147	
148	    String endPoint = conf.getTrimmed(ENDPOINT_KEY, "");
149	    if (StringUtils.isEmpty(endPoint)) {
150	      throw new IllegalArgumentException("Aliyun OSS endpoint should not be " +
151	          "null or empty. Please set proper endpoint with 'fs.oss.endpoint'.");
152	    }
153	    CredentialsProvider provider =
154	        AliyunOSSUtils.getCredentialsProvider(uri, conf);
155	    ossClient = new OSSClient(endPoint, provider, clientConf);
156	    uploadPartSize = AliyunOSSUtils.getMultipartSizeProperty(conf,
157	        MULTIPART_UPLOAD_PART_SIZE_KEY, MULTIPART_UPLOAD_PART_SIZE_DEFAULT);
158	
159	    serverSideEncryptionAlgorithm =
160	        conf.get(SERVER_SIDE_ENCRYPTION_ALGORITHM_KEY, "");
161	
162	    bucketName = uri.getHost();
163	
164	    String cannedACLName = conf.get(CANNED_ACL_KEY, CANNED_ACL_DEFAULT);
165	    if (StringUtils.isNotEmpty(cannedACLName)) {
166	      CannedAccessControlList cannedACL =
167	          CannedAccessControlList.valueOf(cannedACLName);
168	      ossClient.setBucketAcl(bucketName, cannedACL);
169	      statistics.incrementWriteOps(1);
170	    }
171	
172	    maxKeys = conf.getInt(MAX_PAGING_KEYS_KEY, MAX_PAGING_KEYS_DEFAULT);
173	  }
