175	  /**
176	   * Delete an object, and update write operation statistics.
177	   *
178	   * @param key key to blob to delete.
179	   */
180	  public void deleteObject(String key) {
181	    ossClient.deleteObject(bucketName, key);
182	    statistics.incrementWriteOps(1);
183	  }
184	
185	  /**
186	   * Delete a list of keys, and update write operation statistics.
187	   *
188	   * @param keysToDelete collection of keys to delete.
189	   * @throws IOException if failed to delete objects.
190	   */
191	  public void deleteObjects(List<String> keysToDelete) throws IOException {
192	    if (CollectionUtils.isEmpty(keysToDelete)) {
193	      LOG.warn("Keys to delete is empty.");
194	      return;
195	    }
196	
197	    int retry = 10;
198	    int tries = 0;
199	    List<String> deleteFailed = keysToDelete;
200	    while(CollectionUtils.isNotEmpty(deleteFailed)) {
201	      DeleteObjectsRequest deleteRequest = new DeleteObjectsRequest(bucketName);
202	      deleteRequest.setKeys(deleteFailed);
203	      // There are two modes to do batch delete:
204	      // 1. detail mode: DeleteObjectsResult.getDeletedObjects returns objects
205	      // which were deleted successfully.
206	      // 2. simple mode: DeleteObjectsResult.getDeletedObjects returns objects
207	      // which were deleted unsuccessfully.
208	      // Here, we choose the simple mode to do batch delete.
209	      deleteRequest.setQuiet(true);
210	      DeleteObjectsResult result = ossClient.deleteObjects(deleteRequest);
211	      statistics.incrementWriteOps(1);
212	      deleteFailed = result.getDeletedObjects();
213	      tries++;
214	      if (tries == retry) {
215	        break;
216	      }
217	    }
218	
219	    if (tries == retry && CollectionUtils.isNotEmpty(deleteFailed)) {
220	      // Most of time, it is impossible to try 10 times, expect the
221	      // Aliyun OSS service problems.
222	      throw new IOException("Failed to delete Aliyun OSS objects for " +
223	          tries + " times.");
224	    }
225	  }
