227	  /**
228	   * Delete a directory from Aliyun OSS.
229	   *
230	   * @param key directory key to delete.
231	   * @throws IOException if failed to delete directory.
232	   */
233	  public void deleteDirs(String key) throws IOException {
234	    key = AliyunOSSUtils.maybeAddTrailingSlash(key);
235	    ListObjectsRequest listRequest = new ListObjectsRequest(bucketName);
236	    listRequest.setPrefix(key);
237	    listRequest.setDelimiter(null);
238	    listRequest.setMaxKeys(maxKeys);
239	
240	    while (true) {
241	      ObjectListing objects = ossClient.listObjects(listRequest);
242	      statistics.incrementReadOps(1);
243	      List<String> keysToDelete = new ArrayList<String>();
244	      for (OSSObjectSummary objectSummary : objects.getObjectSummaries()) {
245	        keysToDelete.add(objectSummary.getKey());
246	      }
247	      deleteObjects(keysToDelete);
248	      if (objects.isTruncated()) {
249	        listRequest.setMarker(objects.getNextMarker());
250	      } else {
251	        break;
252	      }
253	    }
254	  }
