277	   * Upload an empty file as an OSS object, using single upload.
278	   *
279	   * @param key object key.
280	   * @throws IOException if failed to upload object.
281	   */
282	  public void storeEmptyFile(String key) throws IOException {
283	    ObjectMetadata dirMeta = new ObjectMetadata();
284	    byte[] buffer = new byte[0];
285	    ByteArrayInputStream in = new ByteArrayInputStream(buffer);
286	    dirMeta.setContentLength(0);
287	    try {
288	      ossClient.putObject(bucketName, key, in, dirMeta);
289	      statistics.incrementWriteOps(1);
290	    } finally {
291	      in.close();
292	    }
