295	  /**
296	   * Copy an object from source key to destination key.
297	   *
298	   * @param srcKey source key.
299	   * @param srcLen source file length.
300	   * @param dstKey destination key.
301	   * @return true if file is successfully copied.
302	   */
303	  public boolean copyFile(String srcKey, long srcLen, String dstKey) {
304	    try {
305	      //1, try single copy first
306	      return singleCopy(srcKey, dstKey);
307	    } catch (Exception e) {
308	      //2, if failed(shallow copy not supported), then multi part copy
309	      LOG.debug("Exception thrown when copy file: " + srcKey
310	          + ", exception: " + e + ", use multipartCopy instead");
311	      return multipartCopy(srcKey, srcLen, dstKey);
312	    }
313	  }
