315	  /**
316	   * Use single copy to copy an OSS object.
317	   * (The caller should make sure srcPath is a file and dstPath is valid)
318	   *
319	   * @param srcKey source key.
320	   * @param dstKey destination key.
321	   * @return true if object is successfully copied.
322	   */
323	  private boolean singleCopy(String srcKey, String dstKey) {
324	    CopyObjectResult copyResult =
325	        ossClient.copyObject(bucketName, srcKey, bucketName, dstKey);
326	    statistics.incrementWriteOps(1);
327	    LOG.debug(copyResult.getETag());
328	    return true;
329	  }
