331	  /**
332	   * Use multipart copy to copy an OSS object.
333	   * (The caller should make sure srcPath is a file and dstPath is valid)
334	   *
335	   * @param srcKey source key.
336	   * @param contentLength data size of the object to copy.
337	   * @param dstKey destination key.
338	   * @return true if success, or false if upload is aborted.
339	   */
340	  private boolean multipartCopy(String srcKey, long contentLength,
341	      String dstKey) {
342	    long realPartSize =
343	        AliyunOSSUtils.calculatePartSize(contentLength, uploadPartSize);
344	    int partNum = (int) (contentLength / realPartSize);
345	    if (contentLength % realPartSize != 0) {
346	      partNum++;
347	    }
348	    InitiateMultipartUploadRequest initiateMultipartUploadRequest =
349	        new InitiateMultipartUploadRequest(bucketName, dstKey);
350	    ObjectMetadata meta = new ObjectMetadata();
351	    if (StringUtils.isNotEmpty(serverSideEncryptionAlgorithm)) {
352	      meta.setServerSideEncryption(serverSideEncryptionAlgorithm);
353	    }
354	    initiateMultipartUploadRequest.setObjectMetadata(meta);
355	    InitiateMultipartUploadResult initiateMultipartUploadResult =
356	        ossClient.initiateMultipartUpload(initiateMultipartUploadRequest);
357	    String uploadId = initiateMultipartUploadResult.getUploadId();
358	    List<PartETag> partETags = new ArrayList<PartETag>();
359	    try {
360	      for (int i = 0; i < partNum; i++) {
361	        long skipBytes = realPartSize * i;
362	        long size = (realPartSize < contentLength - skipBytes) ?
363	            realPartSize : contentLength - skipBytes;
364	        UploadPartCopyRequest partCopyRequest = new UploadPartCopyRequest();
365	        partCopyRequest.setSourceBucketName(bucketName);
366	        partCopyRequest.setSourceKey(srcKey);
367	        partCopyRequest.setBucketName(bucketName);
368	        partCopyRequest.setKey(dstKey);
369	        partCopyRequest.setUploadId(uploadId);
370	        partCopyRequest.setPartSize(size);
371	        partCopyRequest.setBeginIndex(skipBytes);
372	        partCopyRequest.setPartNumber(i + 1);
373	        UploadPartCopyResult partCopyResult =
374	            ossClient.uploadPartCopy(partCopyRequest);
375	        statistics.incrementWriteOps(1);
376	        statistics.incrementBytesWritten(size);
377	        partETags.add(partCopyResult.getPartETag());
378	      }
379	      CompleteMultipartUploadRequest completeMultipartUploadRequest =
380	          new CompleteMultipartUploadRequest(bucketName, dstKey,
381	              uploadId, partETags);
382	      CompleteMultipartUploadResult completeMultipartUploadResult =
383	          ossClient.completeMultipartUpload(completeMultipartUploadRequest);
384	      LOG.debug(completeMultipartUploadResult.getETag());
385	      return true;
386	    } catch (OSSException | ClientException e) {
387	      AbortMultipartUploadRequest abortMultipartUploadRequest =
388	          new AbortMultipartUploadRequest(bucketName, dstKey, uploadId);
389	      ossClient.abortMultipartUpload(abortMultipartUploadRequest);
390	      return false;
391	    }
392	  }
