394	  /**
395	   * Upload a file as an OSS object, using single upload.
396	   *
397	   * @param key object key.
398	   * @param file local file to upload.
399	   * @throws IOException if failed to upload object.
400	   */
401	  public void uploadObject(String key, File file) throws IOException {
402	    File object = file.getAbsoluteFile();
403	    FileInputStream fis = new FileInputStream(object);
404	    ObjectMetadata meta = new ObjectMetadata();
405	    meta.setContentLength(object.length());
406	    if (StringUtils.isNotEmpty(serverSideEncryptionAlgorithm)) {
407	      meta.setServerSideEncryption(serverSideEncryptionAlgorithm);
408	    }
409	    try {
410	      PutObjectResult result = ossClient.putObject(bucketName, key, fis, meta);
411	      LOG.debug(result.getETag());
412	      statistics.incrementWriteOps(1);
413	    } finally {
414	      fis.close();
415	    }
416	  }
