427	  public ObjectListing listObjects(String prefix, int maxListingLength,
428	      String marker, boolean recursive) {
429	    String delimiter = recursive ? null : "/";
430	    prefix = AliyunOSSUtils.maybeAddTrailingSlash(prefix);
431	    ListObjectsRequest listRequest = new ListObjectsRequest(bucketName);
432	    listRequest.setPrefix(prefix);
433	    listRequest.setDelimiter(delimiter);
434	    listRequest.setMaxKeys(maxListingLength);
435	    listRequest.setMarker(marker);
436	
437	    ObjectListing listing = ossClient.listObjects(listRequest);
438	    statistics.incrementReadOps(1);
439	    return listing;
440	  }
