442	  /**
443	   * Retrieve a part of an object.
444	   *
445	   * @param key the object name that is being retrieved from the Aliyun OSS.
446	   * @param byteStart start position.
447	   * @param byteEnd end position.
448	   * @return This method returns null if the key is not found.
449	   */
450	  public InputStream retrieve(String key, long byteStart, long byteEnd) {
451	    try {
452	      GetObjectRequest request = new GetObjectRequest(bucketName, key);
453	      request.setRange(byteStart, byteEnd);
454	      InputStream in = ossClient.getObject(request).getObjectContent();
455	      statistics.incrementReadOps(1);
456	      return in;
457	    } catch (OSSException | ClientException e) {
458	      LOG.error("Exception thrown when store retrieves key: "
459	              + key + ", exception: " + e);
460	      return null;
461	    }
462	  }
