474	  /**
475	   * Clean up all objects matching the prefix.
476	   *
477	   * @param prefix Aliyun OSS object prefix.
478	   * @throws IOException if failed to clean up objects.
479	   */
480	  public void purge(String prefix) throws IOException {
481	    String key;
482	    try {
483	      ObjectListing objects = listObjects(prefix, maxKeys, null, true);
484	      for (OSSObjectSummary object : objects.getObjectSummaries()) {
485	        key = object.getKey();
486	        ossClient.deleteObject(bucketName, key);
487	        statistics.incrementWriteOps(1);
488	      }
489	
490	      for (String dir: objects.getCommonPrefixes()) {
491	        deleteDirs(dir);
492	      }
493	    } catch (OSSException | ClientException e) {
494	      LOG.error("Failed to purge " + prefix);
495	    }
496	  }
