498	  public RemoteIterator<LocatedFileStatus> singleStatusRemoteIterator(
499	      final FileStatus fileStatus, final BlockLocation[] locations) {
500	    return new RemoteIterator<LocatedFileStatus>() {
501	      private boolean hasNext = true;
502	      @Override
503	      public boolean hasNext() throws IOException {
504	        return fileStatus != null && hasNext;
505	      }
506	
507	      @Override
508	      public LocatedFileStatus next() throws IOException {
509	        if (hasNext()) {
510	          LocatedFileStatus s = new LocatedFileStatus(fileStatus,
511	              fileStatus.isFile() ? locations : null);
512	          hasNext = false;
513	          return s;
514	        } else {
515	          throw new NoSuchElementException();
516	        }
517	      }
518	    };
519	  }
