521	  public RemoteIterator<LocatedFileStatus> createLocatedFileStatusIterator(
522	      final String prefix, final int maxListingLength, FileSystem fs,
523	      PathFilter filter, FileStatusAcceptor acceptor, String delimiter) {
524	    return new RemoteIterator<LocatedFileStatus>() {
525	      private String nextMarker = null;
526	      private boolean firstListing = true;
527	      private boolean meetEnd = false;
528	      private ListIterator<FileStatus> batchIterator;
529	
530	      @Override
531	      public boolean hasNext() throws IOException {
532	        if (firstListing) {
533	          requestNextBatch();
534	          firstListing = false;
535	        }
536	        return batchIterator.hasNext() || requestNextBatch();
537	      }
538	
539	      @Override
540	      public LocatedFileStatus next() throws IOException {
541	        if (hasNext()) {
542	          FileStatus status = batchIterator.next();
543	          BlockLocation[] locations = fs.getFileBlockLocations(status,
544	              0, status.getLen());
545	          return new LocatedFileStatus(
546	              status, status.isFile() ? locations : null);
547	        } else {
548	          throw new NoSuchElementException();
549	        }
550	      }
551	
552	      private boolean requestNextBatch() {
553	        if (meetEnd) {
554	          return false;
555	        }
556	        ListObjectsRequest listRequest = new ListObjectsRequest(bucketName);
557	        listRequest.setPrefix(AliyunOSSUtils.maybeAddTrailingSlash(prefix));
558	        listRequest.setMaxKeys(maxListingLength);
559	        listRequest.setMarker(nextMarker);
560	        listRequest.setDelimiter(delimiter);
561	        ObjectListing listing = ossClient.listObjects(listRequest);
562	        List<FileStatus> stats = new ArrayList<>(
563	            listing.getObjectSummaries().size() +
564	            listing.getCommonPrefixes().size());
565	        for (OSSObjectSummary summary : listing.getObjectSummaries()) {
566	          String key = summary.getKey();
567	          Path path = fs.makeQualified(new Path("/" + key));
568	          if (filter.accept(path) && acceptor.accept(path, summary)) {
569	            FileStatus status = new OSSFileStatus(summary.getSize(),
570	                key.endsWith("/"), 1, fs.getDefaultBlockSize(path),
571	                summary.getLastModified().getTime(), path, username);
572	            stats.add(status);
573	          }
574	        }
575	
576	        for (String commonPrefix : listing.getCommonPrefixes()) {
577	          Path path = fs.makeQualified(new Path("/" + commonPrefix));
578	          if (filter.accept(path) && acceptor.accept(path, commonPrefix)) {
579	            FileStatus status = new OSSFileStatus(0, true, 1, 0, 0,
580	                path, username);
581	            stats.add(status);
582	          }
583	        }
584	
585	        batchIterator = stats.listIterator();
586	        if (listing.isTruncated()) {
587	          nextMarker = listing.getNextMarker();
588	        } else {
589	          meetEnd = true;
590	        }
591	        statistics.incrementReadOps(1);
592	        return batchIterator.hasNext();
593	      }
594	    };
595	  }
