597	  public PartETag uploadPart(File file, String key, String uploadId, int idx)
598	      throws IOException {
599	    InputStream instream = null;
600	    Exception caught = null;
601	    int tries = 3;
602	    while (tries > 0) {
603	      try {
604	        instream = new FileInputStream(file);
605	        UploadPartRequest uploadRequest = new UploadPartRequest();
606	        uploadRequest.setBucketName(bucketName);
607	        uploadRequest.setKey(key);
608	        uploadRequest.setUploadId(uploadId);
609	        uploadRequest.setInputStream(instream);
610	        uploadRequest.setPartSize(file.length());
611	        uploadRequest.setPartNumber(idx);
612	        UploadPartResult uploadResult = ossClient.uploadPart(uploadRequest);
613	        statistics.incrementWriteOps(1);
614	        return uploadResult.getPartETag();
615	      } catch (Exception e) {
616	        LOG.debug("Failed to upload "+ file.getPath() +", " +
617	            "try again.", e);
618	        caught = e;
619	      } finally {
620	        if (instream != null) {
621	          instream.close();
622	          instream = null;
623	        }
624	      }
625	      tries--;
626	    }
627	
628	    assert (caught != null);
629	    throw new IOException("Failed to upload " + file.getPath() +
630	        " for 3 times.", caught);
631	  }
