633	  /**
634	   * Initiate multipart upload.
635	   */
636	  public String getUploadId(String key) {
637	    InitiateMultipartUploadRequest initiateMultipartUploadRequest =
638	        new InitiateMultipartUploadRequest(bucketName, key);
639	    InitiateMultipartUploadResult initiateMultipartUploadResult =
640	        ossClient.initiateMultipartUpload(initiateMultipartUploadRequest);
641	    return initiateMultipartUploadResult.getUploadId();
642	  }
643	
644	  /**
645	   * Complete the specific multipart upload.
646	   */
647	  public CompleteMultipartUploadResult completeMultipartUpload(String key,
648	      String uploadId, List<PartETag> partETags) {
649	    Collections.sort(partETags, new PartNumberAscendComparator());
650	    CompleteMultipartUploadRequest completeMultipartUploadRequest =
651	        new CompleteMultipartUploadRequest(bucketName, key, uploadId,
652	            partETags);
653	    return ossClient.completeMultipartUpload(completeMultipartUploadRequest);
654	  }
