656	  /**
657	   * Abort the specific multipart upload.
658	   */
659	  public void abortMultipartUpload(String key, String uploadId) {
660	    AbortMultipartUploadRequest request = new AbortMultipartUploadRequest(
661	        bucketName, key, uploadId);
662	    ossClient.abortMultipartUpload(request);
663	  }
664	
665	  private static class PartNumberAscendComparator
666	      implements Comparator<PartETag>, Serializable {
667	    @Override
668	    public int compare(PartETag o1, PartETag o2) {
669	      if (o1.getPartNumber() > o2.getPartNumber()) {
670	        return 1;
671	      } else {
672	        return -1;
673	      }
674	    }
675	  }
